e. Volumes of the specified types will not be targeted by the policy. Constraints: o min: 0 o max: 6 (string) ExcludeTags -&gt; (list) [Default policies for EBS-backed AMIs only] Specifies whether to exclude volumes that have specific tags. Constraints: o min: 0 o max: 50 (structure) Specifies a tag for a resource. Key -&gt; (string) [required] The tag key. Constraints: o min: 0 o max: 500 o pattern: [\p{all}]* Value -&gt; (string) [required] The tag value. Constraints: o min: 0 o max: 500 o pattern: [\p{all}]* JSON Syntax: { "PolicyType": "EBS_SNAPSHOT_MANAGEMENT"|"IMAGE_MANAGEMENT"|"EVENT_BASED_POLICY", "ResourceTypes": ["VOLUME"|"INSTANCE", ...], "ResourceLocations": ["CLOUD"|"OUTPOST"|"LOCAL_ZONE", ...], "TargetTags": [ { "Key": "string", "Value": "string" } ... ], "Schedules": [ { "Name": "string", "CopyTags": true|false, "TagsToAdd": [ { "Key": "string", "Value": "string" } ... ], "VariableTags": [ { "Key": "string", "Value": "string" } ... ], "CreateRule": { "Location": "CLOUD"|"OUTPOST_LOCAL"|"LOCAL_ZONE", "Interval": integer, "IntervalUnit": "HOURS", "Times": ["string", ...], "CronExpression": "string", "Scripts": [ { "Stages": ["PRE"|"POST", ...], "ExecutionHandlerService": "AWS_SYSTEMS_MANAGER", "ExecutionHandler": "string", "ExecuteOperationOnScriptFailure": true|false, "ExecutionTimeout": integer, "MaximumRetryCount": integer } ... ] }, "RetainRule": { "Count": integer, "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" }, "FastRestoreRule": { "Count": integer, "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS", "AvailabilityZones": ["string", ...], "AvailabilityZoneIds": ["string", ...] }, "CrossRegionCopyRules": [ { "TargetRegion": "string", "Target": "string", "Encrypted": true|false, "CmkArn": "string", "CopyTags": true|false, "RetainRule": { "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" }, "DeprecateRule": { "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" } } ... ], "ShareRules": [ { "TargetAccounts": ["string", ...], "UnshareInterval": integer, "UnshareIntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" } ... ], "DeprecateRule": { "Count": integer, "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" }, "ArchiveRule": { "RetainRule": { "RetentionArchiveTier": { "Count": integer, "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" } } } } ... ], "Parameters": { "ExcludeBootVolume": true|false, "NoReboot": true|false, "ExcludeDataVolumeTags": [ { "Key": "string", "Value": "string" } ... ] }, "EventSource": { "Type": "MANAGED_CWE", "Parameters": { "EventType": "shareSnapshot", "SnapshotOwner": ["string", ...], "DescriptionRegex": "string" } }, "Actions": [ { "Name": "string", "CrossRegionCopy": [ { "Target": "string", "EncryptionConfiguration": { "Encrypted": true|false, "CmkArn": "string" }, "RetainRule": { "Interval": integer, "IntervalUnit": "DAYS"|"WEEKS"|"MONTHS"|"YEARS" } } ... ] } ... ], "PolicyLanguage": "SIMPLIFIED"|"STANDARD", "ResourceType": "VOLUME"|"INSTANCE", "CreateInterval": integer, "RetainInterval": integer, "CopyTags": true|false, "CrossRegionCopyTargets": [ { "TargetRegion": "string" } ... ], "ExtendDeletion": true|false, "Exclusions": { "ExcludeBootVolumes": true|false, "ExcludeVolumeTypes": ["string", ...], "ExcludeTags": [ { "Key": "string", "Value": "string" } ... ] } }
    /// </summary>
    [CliOption("--policy-details")]
    public string? PolicyDetails { get; set; }

